const fs=require('fs'),path=require('path');const dir=__dirname,root=process.cwd();
const write=(p,s)=>fs.writeFileSync(path.join(dir,p),s.trim()+'\n');
const report=(p,label=p)=>`[${label}](<${path.join(dir,p).replaceAll('\\','/')}>)`;
const refs=[];function L(p,needle){const text=fs.readFileSync(path.join(root,p),'utf8');const pos=needle?text.indexOf(needle):0;if(pos<0)throw Error('Missing anchor '+p+' '+needle);const line=text.slice(0,pos).split('\n').length;refs.push({file:p,line,anchor:needle||null});return `[${p}:${line}](<${path.join(root,p).replaceAll('\\','/')}:${line}>)`;}
const totals=JSON.parse(fs.readFileSync(path.join(dir,'verification/report-test-totals.json')));
